function validate([root]) {
  if (!Array.isArray(root)) return 'root must be a level-order list.';
  if (root.length === 0) return null;
  if (root[0] === null) return 'Write an empty tree as [].';
  const nodes = [{ val: root[0], left: null, right: null }];
  let i = 1;
  for (let q = 0; q < nodes.length && i < root.length; q++) {
    for (const side of ['left', 'right']) {
      if (i < root.length && root[i] !== null) {
        const node = { val: root[i], left: null, right: null };
        nodes[q][side] = node;
        nodes.push(node);
      }
      i++;
    }
  }
  if (i < root.length) return 'Some values have no parent in the level-order list.';
  if (nodes.length > 10) return 'The tree has at most 10 nodes.';
  for (const node of nodes) {
    if (!Number.isInteger(node.val) || node.val < 1 || node.val > 10) return 'Each value is an integer between 1 and 10.';
    if (node.right && !node.left) return 'Every right child needs a left sibling.';
    if (node.right && (node.right.left || node.right.right)) return 'Every right child must be a leaf.';
  }
  return null;
}

