function upsideDownBinaryTree(root) {
  if (!root) return null;
  const spine = [];
  for (let node = root; node; node = node.left) spine.push(node);
  const rights = spine.map(node => node.right);
  for (let i = spine.length - 1; i > 0; i--) {
    spine[i].left = rights[i - 1];
    spine[i].right = spine[i - 1];
  }
  spine[0].left = null;
  spine[0].right = null;
  return spine[spine.length - 1];
}

