function generate(rand, size) {
  if (size === 'small' && rand() < 0.08) return [[]];
  const total = size === 'large' ? 8 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 6);
  const value = () => 1 + Math.floor(rand() * 10);
  const root = { val: value(), left: null, right: null };
  let count = 1;
  let bottom = root;
  // Grow the left path; each new left child may get a leaf as its right sibling.
  while (count < total) {
    bottom.left = { val: value(), left: null, right: null };
    count++;
    if (count < total && rand() < 0.6) {
      bottom.right = { val: value(), left: null, right: null };
      count++;
    }
    bottom = bottom.left;
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (!node) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
